package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamPhysicsWaveBank1 {
  private const val T = "තරංග, ධ්වනිය, ප්‍රකාශ විද්‍යාව හා තාපය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "තරංග, ධ්වනිය, ආලෝකය හා තාපය පිළිබඳ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("තරංග චලිතයක් මඟින් මාධ්‍යයේ පදාර්ථය ප්‍රවාහනය නොකර එක් ස්ථානයක සිට තවත් ස්ථානයකට ප්‍රචාරණය කරන්නේ කුමක්ද?", "ශක්තිය (සහ කැළඹීම)", "පදාර්ථය", "ඝනත්වය", "ස්කන්ධය", "මාධ්‍යයේ අංශු තම සමතුලිත පිහිටුම වටා කම්පනය වෙමින් ශක්තිය පමණක් ගෙන යයි."),
    q("මාධ්‍යයේ අංශු කම්පනය වන දිශාවට ලම්භක දිශාවකට ශක්තිය ප්‍රචාරණය වන තරංග කුමන වර්ගයේ තරංගද?", "තීර්යක් තරංග (Transverse waves)", "අන්වායාම තරංග", "ස්ථාවර තරංග", "ධ්වනි තරංග", "ජල තරංග හා සියලු විද්‍යුත් චුම්භක තරංග තීර්යක් තරංග වේ."),
    q("මාධ්‍යයේ අංශු තරංග ප්‍රචාරණ දිශාවටම සමාන්තරව ඉදිරියට හා පසුපසට කම්පනය වන තරංග කුමන වර්ගයට අයත්ද?", "අන්වායාම තරංග (Longitudinal waves)", "තීර්යක් තරංග", "ආලෝක තරංග", "X-කිරණ", "වාතය හරහා ගමන් කරන ධ්වනි තරංග සම්පීඩන හා විරලන මගින් යන අන්වායාම තරංග වේ."),
    q("තත්පර 1 කදී යම් ලක්ෂ්‍යයක් පසු කර යන සම්පූර්ණ තරංග (දෝලන) ගණන හඳුන්වන්නේ කුමන නමින්ද?", "සංඛ්‍යාතය (Frequency - Hz)", "තරංග ආයාමය", "විස්තාරය", "ආවර්ත කාලය", "සංඛ්‍යාතය f = 1 / T වේ."),
    q("සංඛ්‍යාතය 500 Hz සහ තරංග ආයාමය 0.68 m වූ ධ්වනි තරංගයක වාතයේ වේගය කීයද?", "340 m s⁻¹", "735 m s⁻¹", "500.68 m s⁻¹", "170 m s⁻¹", "v = fλ = 500 × 0.68 = 340 m s⁻¹."),
    q("වේගය 3 × 10⁸ m s⁻¹ වන රේඩියෝ තරංගයක සංඛ්‍යාතය 100 MHz (10⁸ Hz) නම් එහි තරංග ආයාමය කීයද?", "3 m", "30 m", "0.3 m", "300 m", "λ = v / f = (3 × 10⁸) / 10⁸ = 3 m."),
    q("රළු තරංගයක 'විස්තාරය' (Amplitude) වැඩි වීමෙන් ධ්වනියේ කුමන ලක්ෂණය වැඩි වේද?", "හඬේ සැර / විශාලත්වය (Loudness)", "තාරතාව (Pitch)", "ධ්වනි ගුණය", "වේගය", "ධ්වනි විස්තාරය හඬේ සැරට ද සංඛ්‍යාතය තාරතාවට ද සම්බන්ධ වේ."),
    q("ගිටාරයක කම්බියක ආතතිය වැඩි කර හෝ කෙටි කර වාදනය කරන විට ශබ්දයේ ඉහළ යන ගුණය කුමක්ද?", "තාරතාව (Pitch) — සංඛ්‍යාතය වැඩි වීම", "විස්තාරය", "තරංග ආයාමය", "වේගය", "කාන්තා කටහඬේ සංඛ්‍යාතය පිරිමි කටහඬට වඩා වැඩි බැවින් තාරතාව ඉහළය."),
    q("එකම ස්වරය (සමාන සංඛ්‍යාතය හා සැර) වයලීනයකින් හා බටනලාවකින් වාදනය කළ විට අපට එම සංගීත භාණ්ඩ දෙක වෙන් කර හඳුනා ගත හැක්කේ කුමන ගුණය නිසාද?", "ධ්වනි ගුණය (Quality / Timbre)", "තාරතාව", "වේගය", "පරාවර්තනය", "මූලික සංඛ්‍යාතය සමඟ මුසු වන උපරිතාන (Overtones) රටාව අනුව ධ්වනි ගුණය වෙනස් වේ."),
    q("නිරෝගී මිනිස් කනකට සාමාන්‍යයෙන් ඇසෙන ධ්වනි සංඛ්‍යාත පරාසය (ශ්‍රව්‍ය පරාසය) කොපමණද?", "20 Hz සිට 20,000 Hz (20 kHz) දක්වා", "0 Hz සිට 100 Hz දක්වා", "20,000 Hz ට වැඩි", "1 Hz සිට 1000 Hz දක්වා", "20 Hz ට අඩු ශබ්ද අධෝධ්වනි ද 20,000 Hz ට වැඩි ශබ්ද අතිධ්වනි ද වේ."),
    q("සාගරයේ ගැඹුර මැනීමට (SONAR), ගර්භණී මව්වරුන් ස්කෑන් කිරීමට හා වවුලන්ට රාත්‍රියේ ගමන් කිරීමට උපකාරී වන්නේ කුමන තරංගද?", "අතිධ්වනි තරංග (Ultrasound > 20 kHz)", "අධෝරක්ත කිරණ", "X-කිරණ", "අධෝධ්වනි තරංග", "අතිධ්වනි තරංග කෙටි තරංග ආයාම නිසා පහසුවෙන් පරාවර්තනය වී තියුණු ප්‍රතිබිම්බ දෙයි."),
    q("මුහුදු පතුලට යැවූ SONAR අතිධ්වනි සංඥාවක් නැවත පැමිණීමට තත්පර 4 ක් ගත විය. ජලයේ ධ්වනි වේගය 1500 m s⁻¹ නම් මුහුදේ ගැඹුර කීයද?", "3,000 m", "6,000 m", "1,500 m", "375 m", "යෑමට පමණක් කාලය = 4 / 2 = 2 s; ගැඹුර = 1500 × 2 = 3,000 m."),
    q("පැහැදිලි ප්‍රතිධ්වනියක් (Echo) කනට වෙන් වී ඇසීමට මුල් ශබ්දය හා ප්‍රතිධ්වනිය අතර අවම වශයෙන් තිබිය යුතු කාල පරතරය කීයද?", "0.1 s", "1.0 s", "0.01 s", "2.0 s", "වාතයේ ධ්වනි වේගය 340 m s⁻¹ විට අවම පරාවර්තක දුර ~17 m විය යුතුය."),
    q("රික්තයක් තුළ ධ්වනි තරංග ප්‍රචාරණය නොවී ආලෝක තරංග පමණක් ගමන් කිරීමට හේතුව කුමක්ද?", "ධ්වනි තරංග යාන්ත්‍රික තරංග වන බැවින් මාධ්‍යයක් අවශ්‍ය වීම (ආලෝකය විද්‍යුත් චුම්භක වේ)", "ආලෝකය සෙමෙන් ගමන් කිරීම", "ධ්වනියේ විස්තාරය අඩු වීම", "රික්තය ආලෝකය නිපදවීම", "සඳ මත සිටින ගගනගාමීන් කතා කිරීමට රේඩියෝ තරංග භාවිත කරන්නේ වාතය නොමැති නිසාය."),
    q("වාතය, ජලය සහ වානේ යන මාධ්‍ය තුනෙහි ධ්වනි වේගය වැඩි වන පිළිවෙළ (අඩුම සිට වැඩිම දක්වා) කුමක්ද?", "වාතය < ජලය < වානේ", "වානේ < ජලය < වාතය", "ජලය < වාතය < වානේ", "සියල්ල සමානය", "අංශු ඉතා ළඟින් ඇති ප්‍රත්‍යාස්ථ ඝන ද්‍රව්‍යවල ධ්වනි වේගය උපරිම (වානේ ~5000 m s⁻¹) වේ."),
    q("විද්‍යුත් චුම්භක වර්ණාවලියේ සියලුම තරංග රික්තයක ගමන් කරන පොදු වේගය කොපමණද?", "3 × 10⁸ m s⁻¹", "340 m s⁻¹", "3 × 10⁶ m s⁻¹", "1500 m s⁻¹", "ගැමා කිරණ, X-කිරණ, UV, දෘශ්‍ය ආලෝකය, IR, ක්ෂුද්‍ර තරංග හා රේඩියෝ තරංග එකම වේගයෙන් ගමන් කරයි."),
    q("විද්‍යුත් චුම්භක වර්ණාවලියේ අඩුම සංඛ්‍යාතය හා දිගුම තරංග ආයාමය ඇති තරංග වර්ගය කුමක්ද?", "රේඩියෝ තරංග", "ගැමා කිරණ", "X-කිරණ", "පාරජම්බුල කිරණ", "සංඛ්‍යාතය වැඩිම හා ශක්තිය වැඩිම තරංග වර්ගය ගැමා කිරණයි."),
    q("රූපවාහිනී දුරස්ථ පාලකවල (Remote controls) හා රාත්‍රී දෘෂ්ටි කැමරාවල භාවිත කරන විද්‍යුත් චුම්භක තරංගය කුමක්ද?", "අධෝරක්ත කිරණ (Infrared / IR)", "X-කිරණ", "ගැමා කිරණ", "අතිධ්වනි තරංග", "රත් වූ සෑම වස්තුවකින්ම අධෝරක්ත (තාප) කිරණ නිකුත් වේ."),
    q("ආලෝක පරාවර්තන නියම අනුව පතන කෝණය 35° නම් පතන කිරණය හා පරාවර්තන කිරණය අතර ඇති මුළු කෝණය කීයද?", "70°", "35°", "55°", "90°", "පතන කෝණය (i) = පරාවර්තන කෝණය (r) = 35° බැවින් මුළු කෝණය 35° + 35° = 70°."),
    q("සමතල දර්පණයකින් සෑදෙන ප්‍රතිබිම්බයක ලක්ෂණයක් නොවන්නේ කුමක්ද?", "ප්‍රතිබිම්බය තිරයක් මතට ගත හැකි තාත්වික එකක් වීම", "වස්තුවේ ප්‍රමාණයට සමාන වීම", "පාර්ශ්වික අපවර්තනයක් තිබීම", "දර්පණයෙන් වස්තු දුරට සමාන දුරකින් ඇතුළතින් පිහිටීම", "සමතල දර්පණය සැමවිටම අතාත්වික, උඩුකුරු ප්‍රතිබිම්බ සාදයි."),
    q("වාහනවල පැති කණ්ණාඩි (Side mirrors) සහ වංගු සහිත මාර්ගවල ආරක්ෂක දර්පණ ලෙස භාවිත කරන වක්‍ර දර්පණ වර්ගය කුමක්ද?", "උත්තල දර්පණය (Convex mirror)", "අවතල දර්පණය", "සමතල දර්පණය", "අවතල කාචය", "උත්තල දර්පණය සැමවිටම උඩුකුරු, කුඩා කළ ප්‍රතිබිම්බයක් සාදා පුළුල් දෘෂ්ටි ක්ෂේත්‍රයක් ලබා දේ."),
    q("දන්ත වෛද්‍යවරුන්ගේ දත් පරීක්ෂා කරන දර්පණය, රැවුල බාන දර්පණය සහ වාහන හෙඩ්ලයිට් පරාවර්තකය ලෙස ගන්නේ කුමන දර්පණයද?", "අවතල දර්පණය (Concave mirror)", "උත්තල දර්පණය", "සමතල දර්පණය", "ප්‍රිස්මය", "අවතල දර්පණයේ නාභියට ඇතුළතින් වස්තුව තැබූ විට විශාල කළ උඩුකුරු අතාත්වික ප්‍රතිබිම්බයක් ලැබේ."),
    q("ආලෝක කිරණයක් විරල මාධ්‍යයක සිට (වාතය) ගහන මාධ්‍යයකට (වීදුරු/ජලය) ඇලව ඇතුළු වන විට සිදුවන්නේ කුමක්ද?", "අභිලම්බය දෙසට නැවී වේගය අඩු වීම", "අභිලම්බයෙන් ඉවතට නැවීම", "වේගය වැඩි වීම", "සංඛ්‍යාතය වෙනස් වීම", "වර්තනයේදී වේගය හා තරංග ආයාමය වෙනස් වුවද සංඛ්‍යාතය නියතව පවතී."),
    q("පිරිසිදු පොකුණක පතුල ඇත්ත වශයෙන්ම පවතින ගැඹුරට වඩා නොගැඹුරු (ඉහළට එසවුණු) ලෙස පෙනෙන්නේ කුමන සංසිද්ධිය නිසාද?", "ආලෝක වර්තනය (Refraction)", "පරාවර්තනය", "විසරණය", "විවර්තනය", "පතුලේ සිට එන ආලෝක කිරණ ජලයෙන් වාතයට යෑමේදී අභිලම්බයෙන් ඉවතට නැවේ."),
    q("පූර්ණ අභ්‍යන්තර පරාවර්තනය (Total internal reflection) සිදුවීමට අවශ්‍ය කොන්දේසි දෙක මොනවාද?", "ආලෝකය ගහන සිට විරල මාධ්‍යයට යෑම සහ පතන කෝණය අවධි කෝණයට වඩා වැඩි වීම", "විරල සිට ගහන මාධ්‍යයට යෑම", "පතන කෝණය 0° වීම", "පතන කෝණය අවධි කෝණයට වඩා අඩු වීම", "ප්‍රකාශ තන්තු (Optical fibres) හා මිරිඟුව මෙම සංසිද්ධිය මත ක්‍රියා කරයි."),
    q("අධිවේගී අන්තර්ජාල සන්නිවේදනයේදී හා වෛද්‍ය එන්ඩොස්කොප් උපකරණවල ආලෝක සංඥා ගෙන යන ප්‍රකාශ තන්තු ක්‍රියා කරන මූලධර්මය කුමක්ද?", "පූර්ණ අභ්‍යන්තර පරාවර්තනය", "ආලෝක විසරණය", "ධ්‍රැවීකරණය", "වර්ණ විභේදනය", "තන්තුව නැවුණද ආලෝකය පිටතට කාන්දු නොවී ඇතුළත පරාවර්තනය වෙමින් ගමන් කරයි."),
    q("අවිදුරදෘෂ්ටිකත්වය (දුර ඇති වස්තු පැහැදිලිව නොපෙනීම / Short-sightedness) නිවැරදි කිරීමට උපැස් යුවළේ යොදන කාච වර්ගය කුමක්ද?", "අවතල කාචය (අපසාරී කාචය)", "උත්තල කාචය", "සිලින්ඩරාකාර කාචය", "සමතල වීදුරු", "දුර වස්තුවලින් එන කිරණ දෘෂ්ටි විතානයට ඉදිරියෙන් නාභිගත වන බැවින් අවතල කාචයකින් කිරණ අපසරණය කෙරේ."),
    q("දුරදෘෂ්ටිකත්වය (ළඟ ඇති පොත්පත් කියවීමට අපහසු වීම / Long-sightedness) නිවැරදි කිරීමට පළඳින උපැස් කාචය කුමක්ද?", "උත්තල කාචය (අභිසාරී කාචය)", "අවතල කාචය", "අවතල දර්පණය", "ප්‍රිස්මය", "කිරණ දෘෂ්ටි විතානයට පිටුපසින් නාභිගත වීම උත්තල කාචය මගින් නිවැරදි කරයි."),
    q("උත්තල කාචයක් ඉදිරියේ වස්තුව නාභියට (F) වඩා ළඟින් (F හා ප්‍රකාශ කේන්ද්‍රය අතර) තැබූ විට ලැබෙන ප්‍රතිබිම්බය කෙබඳුද? (සරල අන්වීක්ෂය)", "උඩුකුරු, විශාල කළ, අතාත්වික ප්‍රතිබිම්බයකි", "යටිකුරු, කුඩා, තාත්වික ප්‍රතිබිම්බයකි", "වස්තුවේ ප්‍රමාණයට සමාන තාත්වික ප්‍රතිබිම්බයකි", "ප්‍රතිබිම්බයක් නොසෑදේ", "අත් කාචය (Magnifying glass) ක්‍රියා කරන්නේ මෙම අවස්ථාව අනුවය."),
    q("උත්තල කාචයක නාභි දුර 20 cm නම් එහි නාභියේ සිට 40 cm (2F) දුරින් තැබූ වස්තුවක ප්‍රතිබිම්බය සෑදෙන්නේ කොතැනද?", "අනෙක් පස 40 cm (2F) දුරින් සමාන ප්‍රමාණයේ යටිකුරු තාත්වික ප්‍රතිබිම්බයකි", "නාභියේදීය", "කාචය තුළය", "අනන්තයේදීය", "වස්තුව 2F හි තැබූ විට ප්‍රතිබිම්බය ද 2F හි සමාන උසින් සෑදේ."),
    q("සූර්යාලෝකය හෙවත් සුදු ආලෝකය වීදුරු ප්‍රිස්මයක් තුළින් යැවූ විට වර්ණ 7 කට බෙදී යාමේ සංසිද්ධිය හඳුන්වන්නේ කෙසේද?", "වර්ණ විභේදනය / අපකිරණය (Dispersion)", "පරාවර්තනය", "විවර්තනය", "ධ්‍රැවීකරණය", "වීදුරු තුළ රතු ආලෝකය අඩුවෙන්ම ද දම් ආලෝකය වැඩියෙන්ම ද නැවේ."),
    q("සුදු ආලෝකය ප්‍රිස්මයක් හරහා අපකිරණය වීමේදී වැඩිම වර්තන කෝණයකට (වැඩිම අපගමනයකට) ලක්වන වර්ණය කුමක්ද?", "දම් (Violet)", "රතු (Red)", "කහ (Yellow)", "කොළ (Green)", "තරංග ආයාමය කෙටි දම් ආලෝකය වීදුරු තුළ සෙමෙන් යන බැවින් වැඩියෙන් නැවේ."),
    q("රතු, කොළ සහ නිල් යන ප්‍රාථමික ආලෝක වර්ණ තුන සමාන තීව්‍රතාවෙන් එකට මිශ්‍ර කළ විට ලැබෙන වර්ණය කුමක්ද?", "සුදු ආලෝකය", "කළු", "දුඹුරු", "දම්", "රූපවාහිනී හා දුරකථන තිර ක්‍රියා කරන්නේ RGB ආලෝක ආකලනයෙනි."),
    q("උෂ්ණත්වය මැනීමේ අන්තර්ජාතික SI ඒකකය කුමක්ද?", "කෙල්වින් (K)", "සෙල්සියස් (°C)", "ෆැරන්හයිට් (°F)", "ජූල් (J)", "T(K) = θ(°C) + 273.15 (සාමාන්‍ය ගණනයේදී + 273)."),
    q("27°C උෂ්ණත්වය කෙල්වින් (K) පරිමාණයෙන් කොපමණද?", "300 K", "246 K", "273 K", "327 K", "T = 27 + 273 = 300 K."),
    q("සෙල්සියස් පරිමාණයේ 0°C සිට 4°C දක්වා ජලය රත් කරන විට ජලයේ පරිමාවට සිදුවන අසාමාන්‍ය හැසිරීම කුමක්ද?", "ජලය ප්‍රසාරණය වනු වෙනුවට සංකෝචනය වේ (ඝනත්වය 4°C දී උපරිම වේ)", "ජලය වාෂ්ප වේ", "පරිමාව 10 ගුණයකින් වැඩි වේ", "ජලය ගල් වේ", "ජලයේ අසමමිතික ප්‍රසාරණය (Anomalous expansion) ජලජ ජීවීන් ශීත සෘතුවේදී ආරක්ෂා කරයි."),
    q("රේල් පීලි අතර කුඩා හිඩැස් තැබීම හා දුරකථන රැහැන් කණු අතර බුරුල්ව එල්ලීම සිදු කරන්නේ කුමන භෞතික සිද්ධාන්තය නිසාද?", "ඝන ද්‍රව්‍යවල තාප ප්‍රසාරණය හා සංකෝචනය", "චුම්භක ප්‍රේරණය", "වායුගෝලීය පීඩනය", "විසරණය", "උණුසුම් දිනවල පීලි ප්‍රසාරණය වී ඇදවීමත්, සීතල රාත්‍රියේ කම්බි සංකෝචනය වී කැඩීමත් වළකයි."),
    q("විදුලි ඉස්තිරික්කයක හා රයිස් කුකරයක නියමිත උෂ්ණත්වයේදී ස්වයංක්‍රීයව විදුලිය විසන්ධි කරන තාපස්ථායකයේ (Thermostat) අඩංගු වන්නේ කුමක්ද?", "ද්විලෝහ තීරුවක් (Bimetallic strip - උදා: පිත්තල හා යකඩ)", "රසදිය බටයක්", "වීදුරු කාචයක්", "මිනිරන් දණ්ඩක්", "රත් වූ විට පිත්තල යකඩවලට වඩා වැඩියෙන් ප්‍රසාරණය වී තීරුව නැමී පරිපථය විසන්ධි කරයි."),
    q("සංවාහන ධාරා (Convection currents) මගින් තාපය සම්ප්‍රේෂණය විය හැක්කේ කුමන මාධ්‍යවල පමණද?", "ද්‍රව සහ වායු (තරල) තුළ", "ඝන ද්‍රව්‍ය හා රික්තය තුළ", "රික්තය තුළ පමණි", "ලෝහ තුළ පමණි", "රත් වූ තරලය ඝනත්වය අඩු වී ඉහළ යන අතර සිසිල් තරලය පහළට පැමිණේ."),
    q("සූර්යයාගේ සිට පෘථිවිය වෙත අභ්‍යවකාශයේ රික්තය හරහා තාපය පැමිණෙන තාප සංක්‍රමණ ක්‍රමය කුමක්ද?", "විකිරණය (Radiation)", "සන්නයනය", "සංවහනය", "වාෂ්පීභවනය", "තාප විකිරණය අධෝරක්ත විද්‍යුත් චුම්භක තරංග ලෙස ගමන් කරන බැවින් මාධ්‍යයක් අවශ්‍ය නොවේ."),
    q("උණු වතුර දැමූ තාප ප්ලාස්කුවක (Thermos flask) රික්ත ස්තරය, රිදී ආලේපිත බිත්ති සහ ප්ලාස්ටික් පියන පිළිවෙළින් වළක්වන තාප හානි ක්‍රම මොනවාද?", "සන්නයන/සංවහනය, විකිරණය සහ වාෂ්පීභවනය/සංවහනය", "විකිරණය පමණක්", "සන්නයනය පමණක්", "ආලෝක පරාවර්තනය පමණක්", "මෙම නිර්මාණය මගින් සියලුම තාප හුවමාරු ක්‍රම අවම කෙරේ."),
    q("උණුසුම් ග්‍රීෂ්ම දිනවල සුදු හෝ ලා පැහැති ඇඳුම් ඇඳීමට නිර්දේශ කරන්නේ ඇයි?", "සුදු පෘෂ්ඨ තාප විකිරණයෙන් වැඩි කොටසක් පරාවර්තනය කර අඩුවෙන් අවශෝෂණය කිරීම", "සුදු පැහැයෙන් තාපය වැඩිපුර උරාගන්නා නිසා", "සුදු රෙදිවල තාප සන්නායකතාව ඉහළ නිසා", "කළු පැහැය පරාවර්තකයක් වන නිසා", "කළු රළු පෘෂ්ඨ හොඳ විකිරණ අවශෝෂක මෙන්ම හොඳ විකිරණ විමෝචක ද වේ."),
    q("ජලය 2 kg ක උෂ්ණත්වය 30°C සිට 80°C දක්වා ඉහළ නැංවීමට සැපයිය යුතු තාප ශක්තිය කීයද? (ජලයේ c = 4200 J kg⁻¹ °C⁻¹)", "420,000 J (420 kJ)", "84,000 J", "42,000 J", "210,000 J", "Δθ = 80 - 30 = 50°C; Q = 2 × 4200 × 50 = 420,000 J."),
    q("වාෂ්පීභවනය හා නැටීම (Boiling) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "වාෂ්පීභවනය ඕනෑම උෂ්ණත්වයකදී පෘෂ්ඨයෙන් සිදුවන අතර නැටීම නියත තාපාංකයේදී සිදුවේ", "නැටීම පෘෂ්ඨයේ පමණක් සිදුවේ", "වාෂ්පීභවනය 100°C දී පමණක් සිදුවේ", "දෙකම එකම ක්‍රියාවලියකි", "වාෂ්පීභවනය නිසා ඉතිරි වන ද්‍රවය සිසිල් වේ."),
    q("සම්මත පීඩනයේදී 0°C පවතින අයිස් කුට්ටියක් සම්පූර්ණයෙන්ම 0°C ජලය බවට දියවීමේදී උෂ්ණත්වමානයේ පාඨාංකය නොවෙනස්ව පවතින්නේ ඇයි?", "ලබා දෙන තාපය අණු අතර බන්ධන ලිහිල් කර අවස්ථා විපර්යාසයට (විලයන ගුප්ත තාපය) වැය වන නිසා", "තාපමානය කැඩී ඇති නිසා", "අයිස් තාපය පරාවර්තනය කරන නිසා", "තාපය ජලයෙන් පිටවන නිසා", "අවස්ථා විපර්යාසය අතරතුර උෂ්ණත්වය නියතව පවතී."),
